import re
for i,r in enumerate(rows):
 t=''.join(x.get('text','') for x in r.get('message',{}).get('content',[]) if isinstance(x,dict))
 if 'Demo pair' in t and 'output' in t:
  mi=re.search(r'Demo pair (\d+) input \(.*?\):\n(.*?)\nDemo pair \1 output \(.*?\):\n(.*?)(?:\n\nSame instance|$)',t,re.S)
  if mi:
   n=int(mi.group(1)); inp=[[int(x) for x in line.split()] for line in mi.group(2).splitlines()]; out=[[int(x) for x in line.split()] for line in mi.group(3).splitlines()]
   color=next(c for row in inp for c in row if c!=inp[0][0])
   changed=[(y,x) for y,row in enumerate(inp) for x,v in enumerate(row) if out[y][x]==2 and v!=2]
   print(n, 'color',color,'shape',len(inp),len(inp[0]),'changes',len(changed), 'coords',changed[:30])
